   const ids=[...new Set(g.itemIds.filter(Boolean))];
   for(const id of ids){
    const ref=doc(db,'inventory',id),snap=await getDoc(ref);
    if(!snap.exists())throw new Error('Linked inventory item missing: '+id);
    const item=snap.data(),bs=(Array.isArray(item.stockBalances)?item.stockBalances:[]).map(b=>({...b}));
    let changed=false;
    for(const b of bs){
     if(b.locationType!=='client'||String(b.locationId||'')!==String(g.businessId||''))continue;
     if(String(b.clientCommercialKey||'')===String(g.key||'')){b.clientCommercialKey=newKey;b.clientPONumber=newPO;changed=true;}
     if(String(b.extensionCommercialKey||'')===String(g.key||'')){b.extensionCommercialKey=newKey;b.extensionPONumber=newPO;changed=true;}
    }
    if(changed)batch.update(ref,{stockBalances:bs,lastEditedAt:at,lastEditedBy:a.email});
   }
   const moves=await getDocs(query(collection(db,'movements'),where('referenceNumber','==',g.poNumber),limit(400)));
   if(moves.size===400)throw new Error('Too many linked movements to rename safely.');
   for(const m of moves.docs){const x=m.data();if(String(x.toId||'')!==String(g.businessId||'')||x.toType!=='client')continue;batch.update(m.ref,{documentClientPO:newPO,documentUpdatedAt:at,documentUpdatedBy:a.email});}
   // Pending refs may have originated in a separate movement group with no PO yet.
