   if(!remove&&list.some((x,i)=>i!==index&&norm(x.number)===norm(no)&&(type==='INV'||x.type===type&&(type!=='OTHER'||norm(x.customType)===norm(customType)))))throw new Error('Document already attached. Edit its linked items instead.');
   const before=index>=0?list[index]:null;
