async function readBatched(name,filters=[]){const rows=[];let cursor=null;while(true){const parts=[...filters,orderBy(documentId(),'asc')];if(cursor)parts.push(startAfter(cursor));parts.push(limit(READ_BATCH));const snap=await getDocs(query(collection(db,name),...parts));for(const d of snap.docs)rows.push({id:d.id,...d.data()});if(snap.size<READ_BATCH)break;cursor=snap.docs.at(-1);}return rows;}
async function syncLegacyIndex(){if(!can('documents.edit'))return;const btn=$('docSyncIndex');if(btn){btn.disabled=true;btn.textContent='Syncing...';}try{const a=await actor(),existing=await readBatched('document_refs'),keys=new Set(existing.filter(x=>x.docType==='Commercial PO'&&x.commercialKey).map(x=>x.commercialKey)),created=[];const clientGroups=await readBatched('movement_groups',[where('referenceType','==','client_po')]);for(const g of clientGroups){const po=String(g.referenceNumber||'').trim(),businessId=String(g.partyId||g.toId||'');if(!po||po.startsWith('PENDING-')||!businessId)continue;const k=key('client',businessId,po);if(keys.has(k))continue;const moves=await readBatched('movements',[where('movementGroupId','==',g.id)]),ids=[...new Set(moves.map(x=>x.itemId).filter(Boolean))],first=moves[0]||{},r=doc(collection(db,'document_refs')),rec={docType:'Commercial PO',context:'Commercial Documents',commercialKey:k,commercialSide:'client',businessId,businessName:g.partyName||g.toName||'',poNumber:po,refNumber:po,poAmount:Number(first.clientPOAmount||0),currency:first.currency||'MYR',poStatus:'Open',expectedQty:null,fulfilledQty:ids.length,periodFrom:first.periodFrom||'',periodTo:first.periodTo||'',linkedItemIds:ids,invoices:[],createdAt:g.createdAt||g.updatedAt||now(),createdBy:a.email};await setDoc(r,rec);keys.add(k);created.push(k);}const owned=await readBatched('registration_batches',[where('ownershipType','==','owned')]),r2r=await readBatched('inventory',[where('ownershipType','==','third_party')]),supplierMap=new Map();for(const b of owned){const po=String(b.ourPONumber||'').trim(),businessId=String(b.supplierId||'');if(!po||!businessId)continue;const k=key('supplier',businessId,po),x=supplierMap.get(k)||{businessId,businessName:b.supplierName||'',po,amount:0,currency:b.currency||'MYR',ids:[],qty:0,createdAt:b.createdAt||''};x.ids.push(...(Array.isArray(b.itemIds)?b.itemIds.filter(Boolean):[]));x.qty+=Number(b.quantity||0);x.amount=Math.max(x.amount,Number(b.ourPOAmount||0));supplierMap.set(k,x);}for(const i of r2r){if(!i.ourPONumber||i.status==='Returned to Owner')continue;const businessId=String(i.ownerBusinessId||i.supplierId||'');if(!businessId)continue;const k=key('supplier',businessId,i.ourPONumber),x=supplierMap.get(k)||{businessId,businessName:i.ownerBusinessName||i.supplierName||'',po:i.ourPONumber,amount:0,currency:i.currency||'MYR',ids:[],qty:0,createdAt:i.createdAt||''};x.ids.push(i.id);x.qty++;x.amount=Math.max(x.amount,Number(i.ourPOAmount||0));supplierMap.set(k,x);}for(const[k,x]of supplierMap){if(keys.has(k))continue;const ids=[...new Set(x.ids)],r=doc(collection(db,'document_refs'));await setDoc(r,{docType:'Commercial PO',context:'Commercial Documents',commercialKey:k,commercialSide:'supplier',businessId:x.businessId,businessName:x.businessName,poNumber:x.po,refNumber:x.po,poAmount:x.amount,currency:x.currency||'MYR',poStatus:'Open',expectedQty:Math.max(x.qty,ids.length)||null,fulfilledQty:ids.length,periodFrom:'',periodTo:'',linkedItemIds:ids,invoices:[],createdAt:x.createdAt||now(),createdBy:a.email});keys.add(k);created.push(k);}await addDoc(collection(db,'audit_traces'),{traceVersion:3,actionType:'SYNC_COMMERCIAL_PO_INDEX',module:'Documents',targetType:'document_refs',targetName:'Commercial PO Index',targetId:'',summary:`Sync legacy Commercial PO index: ${created.length} record(s) created`,beforeValue:null,afterValue:{created:created.length},changedFields:['document_refs'],remark:'One-time legacy source synchronization. Normal Documents browsing uses document_refs only.',performedBy:a.email,performedByRole:a.role,performedAt:now()});alert(`Commercial PO index sync complete. ${created.length} missing PO record(s) indexed.`);await show(true);}catch(e){console.error('IMS PO index sync failed:',e);alert('PO index sync failed: '+(e?.message||e));}finally{if(btn){btn.disabled=false;btn.textContent='Sync Legacy PO Index';}}}



function deliveryPO(m){return Object.prototype.hasOwnProperty.call(m,'documentClientPO')?String(m.documentClientPO||'').trim():(String(m.referenceNumber||'').startsWith('PENDING-')?'':String(m.referenceType||'')==='client_po'?String(m.referenceNumber||'').trim():'');}
function deliveryKey(m){
 const po=deliveryPO(m);
 // A received PO belongs to one client document even if stock was dispatched in several movement batches.
 if(po)return 'po|'+String(m.toId||norm(m.toName))+'|'+norm(po);
 // PO-pending records still need a stable internal movement group rather than a synthetic PO number.
 return 'pending|'+String(m.movementGroupId||m.movementBatchId||m.movementId||m.id);
}
async function loadClientDeliveries(){
 clientDeliveryRows=[];
 if(side!=='client'||page!==0)return;
 let snaps=[];
 if(docFilter.po){
  snaps=await Promise.all([
   getDocs(query(collection(db,'movements'),where('referenceNumber','==',docFilter.po),limit(100))),
   getDocs(query(collection(db,'movements'),where('documentClientPO','==',docFilter.po),limit(100)))
  ]);
 }else{
  snaps=[await getDocs(query(collection(db,'movements'),where('toType','==','client'),orderBy(documentId(),'desc'),limit(100)))];
 }
 const seen=new Set(),byDocument=new Map();
 for(const snap of snaps)for(const d of snap.docs){
  if(seen.has(d.id))continue;seen.add(d.id);
  const m={id:d.id,...d.data()};
  if(m.toType!=='client')continue;
  const k=deliveryKey(m),g=byDocument.get(k);
  if(g){
   g.itemIds.push(m.itemId);g.qty+=Number(m.qty||0);g.movements.push(m);
   if(String(m.createdAt||'')>String(g.createdAt||''))g.createdAt=m.createdAt;
  }else byDocument.set(k,{...m,documentKey:k,itemIds:[m.itemId],qty:Number(m.qty||0),movements:[m]});
 }
 const candidates=[...byDocument.values()].filter(m=>{
  if(docFilter.po&&m.movements.every(x=>deliveryPO(x)!==docFilter.po))return false;
  if(docFilter.status==='Pending PO')return m.movements.every(x=>!deliveryPO(x));
  if(docFilter.status&&m.status!==docFilter.status)return false;
  return true;
 });
 // Do not show an already indexed PO for a second time as a delivery row.
 // The canonical Client PO remains the single tracking document for its associated movements.
 const linkedKeys=new Set(groups.filter(g=>g.side==='client').map(g=>g.key));
 const keysToCheck=[...new Set(candidates.filter(m=>deliveryPO(m)&&m.toId).map(m=>key('client',m.toId,deliveryPO(m))))].filter(k=>!linkedKeys.has(k));
 // Limit reads to one lookup per distinct client PO, not one per delivered item.
 for(let i=0;i<keysToCheck.length;i+=15){
  const chunk=keysToCheck.slice(i,i+15);
  const matches=await Promise.all(chunk.map(k=>getDocs(query(collection(db,'document_refs'),where('commercialKey','==',k),limit(1)))));
  matches.forEach((snap,n)=>{if(!snap.empty)linkedKeys.add(chunk[n]);});
 }
 clientDeliveryRows=candidates.filter(m=>!deliveryPO(m)||!linkedKeys.has(key('client',m.toId||'',deliveryPO(m)))).sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));
}
function deliveryRowsHtml(){
 if(side!=='client'||page!==0)return'';
 return clientDeliveryRows.map(m=>{
  const po=deliveryPO(m),pending=!po;
  const count=new Set(m.itemIds.filter(Boolean)).size;
  return '<tr class="border-t border-slate-800 '+(pending?'bg-amber-950/20':'')+'"><td class="p-2 font-semibold">'+(pending?'<span class="text-amber-300">Pending PO</span>':esc(po))+'<div class="text-[10px] text-slate-500">Delivery · '+count+' item(s) · '+m.movements.length+' movement record(s)</div></td><td class="p-2">'+esc(m.toName||'')+'</td><td class="p-2">'+esc(m.status||'')+'</td><td class="p-2">'+esc((m.createdAt||'').slice(0,10))+'</td><td class="p-2">'+esc(m.documentPeriodTo||m.periodTo||'—')+'</td><td class="p-2 text-right">—</td><td class="p-2 text-right">'+m.qty+'</td><td class="p-2 text-right">—</td><td class="p-2 text-right">'+esc(m.documentCurrency||m.currency||'MYR')+' '+money(Number(m.documentPOAmount??m.clientPOAmount??0))+'</td><td class="p-2 text-right">—</td><td class="p-2 text-right">—</td><td class="p-2"><button class="openDelivery bg-slate-700 px-3 py-1.5 rounded-lg" data-batch="'+esc(deliveryKey(m))+'">Open</button></td></tr>';
 }).join('');
}
function movementDocInput(label,id,value='',type='text'){return '<label class="block text-xs text-slate-400">'+esc(label)+'<input id="'+id+'" type="'+type+'" class="'+cls+' mt-1" value="'+esc(value??'')+'"></label>';}
function movementEffective(m,field,fallback){return Object.prototype.hasOwnProperty.call(m,field)?m[field]:fallback;}
// Client deliveries without a canonical PO are registered into the same document_refs
// index as owned stock. Both ownership types then use openPO, savePO, attachInvoice and extendPO.
async function openDelivery(k){
 const m=clientDeliveryRows.find(x=>deliveryKey(x)===k);
 if(!m)return;
 const clientId=String(m.toId||''),po=deliveryPO(m),pending=!po;
 if(!clientId)return alert('Delivery has no linked client business ID. Correct its movement link before creating a PO.');
 const sourceRef=String(m.referenceNumber||'').trim();
 const placeholder=sourceRef&&sourceRef.startsWith('PENDING-')?sourceRef:'PENDING-'+String(m.movementGroupId||m.movementBatchId||m.id);
 const number=po||placeholder,commercialKey=key('client',clientId,number);
 try{
  const indexed=await fetchPOByKey(commercialKey);
  if(indexed){await openPO(indexed);return;}
  if(!can('documents.add'))return alert('A manager must register this delivery into Client Documents before it can be edited.');
  const ids=[...new Set(m.itemIds.filter(Boolean))],a=await actor(),at=now();
  const ref=doc(collection(db,'document_refs'));
  const rec={docType:'Commercial PO',context:'Commercial Documents',commercialKey,commercialSide:'client',
   businessId:clientId,businessName:m.toName||'',poNumber:number,refNumber:number,
   poAmount:Number(m.documentPOAmount??m.clientPOAmount??0),currency:m.documentCurrency||m.currency||'MYR',
   poStatus:pending?'Pending PO':'Open',expectedQty:null,fulfilledQty:ids.length,linkedItemIds:ids,
   periodFrom:m.documentPeriodFrom||m.periodFrom||'',periodTo:m.documentPeriodTo||m.periodTo||'',
   invoices:m.documentInvoice?[{number:m.documentInvoice,date:m.documentInvoiceDate||'',amount:Number(m.documentInvoiceAmount||0),currency:m.documentCurrency||m.currency||'MYR',createdAt:m.documentUpdatedAt||m.createdAt||at}]:[],movementGroupId:m.movementGroupId||'',movementIds:m.movements.map(x=>x.id),
   createdAt:m.createdAt||at,createdBy:a.email,indexedAt:at,indexedBy:a.email};
  // A repeat click uses the existing canonical entry, never creates a second movement.
  // Writes are scoped to the PO index: physical inventory records are not altered here.
  await setDoc(ref,rec);
  await addDoc(collection(db,'audit_traces'),{traceVersion:3,actionType:'INDEX_CLIENT_DELIVERY_PO',
   module:'Documents',targetType:'commercial_po',targetName:po||'Pending PO',targetId:ref.id,
   summary:'Record completed client delivery in canonical Client PO tracking',beforeValue:null,
   afterValue:{commercialKey,itemIds:ids,movementIds:rec.movementIds},
   changedFields:['document_refs'],performedBy:a.email,performedByRole:a.role,performedAt:at});
  await openPO(fromRef({id:ref.id,...rec}));
 }catch(e){console.error('Open client delivery as PO failed',e);alert('Unable to open Client PO: '+(e?.message||e));}
}

function render(){setHead();const dueCount=side==='client'?groups.filter(actionableDue).length:0,pendingCount=groups.filter(g=>g.status!=='Cancelled').reduce((n,g)=>n+(g.unallocated?0:g.pendingIds.length),0),reviewCount=groups.filter(g=>g.status!=='Cancelled'&&g.unallocated).length,statuses=['Open','Pending PO','Partially Fulfilled','Fulfilled / Completed','Extended / Superseded','Cancelled','Closed'];$('appContent').innerHTML=`${tabs()}${dueCount?`<div class="mb-4 border border-red-700 bg-red-950/40 rounded-xl p-3 text-sm text-red-200"><b>${dueCount} client PO${dueCount===1?'':'s'} due on this page.</b></div>`:''}<div class="mb-4 flex flex-wrap gap-2"><button id="docInvoiceAlert" class="border border-amber-700 bg-amber-950/30 rounded-xl p-3 text-sm text-amber-200"><b>${pendingCount} pending invoice item links</b> · this page</button>${reviewCount?`<button id="docInvoiceReview" class="border border-slate-600 rounded-xl p-3 text-sm">${reviewCount} PO(s) with unallocated legacy invoices · review</button>`:''}</div><section class="bg-slate-900 border border-slate-800 rounded-2xl p-4"><div class="flex flex-wrap items-end gap-2"><label class="text-[10px] text-slate-500">Exact PO Number<input id="docSearch" value="${esc(docFilter.po)}" class="${cls} mt-1" placeholder="Exact PO"></label><label class="text-[10px] text-slate-500">Status<select id="docStatusFilter" class="${cls} mt-1"><option value="">All Statuses</option>${statuses.map(s=>`<option ${s===docFilter.status?'selected':''}>${esc(s)}</option>`).join('')}</select></label><button id="docApply" class="bg-red-600 px-4 py-2.5 rounded-lg text-xs font-bold">Apply Server Filter</button><button id="docClear" class="bg-slate-700 px-4 py-2.5 rounded-lg text-xs font-bold">Clear</button>${can('documents.edit')?'<button id="docSyncIndex" class="bg-cyan-800 px-4 py-2.5 rounded-lg text-xs font-bold ml-auto">Sync Legacy PO Index</button>':''}</div><div class="text-[11px] text-slate-500 mt-2">Client Documents uses one PO detail format for owned and R2R items. Unindexed recent deliveries can be opened and registered in the same PO index. Browse shows the latest 100 movement records; older records require an exact reference lookup.</div><div id="docTable" class="mt-4"></div></section><div id="docDetail" class="mt-5"></div>`;$('docClient').onclick=()=>switchSide('client');$('docSupplier').onclick=()=>switchSide('supplier');$('docApply').onclick=()=>applyFilters();$('docClear').onclick=()=>clearFilters();if($('docSearch'))$('docSearch').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();applyFilters();}};if($('docSyncIndex'))$('docSyncIndex').onclick=syncLegacyIndex;renderRows();for(const id of ['docInvoiceAlert','docInvoiceReview'])if($(id))$(id).onclick=()=>{const hits=groups.filter(g=>g.status!=='Cancelled'&&(id==='docInvoiceReview'?g.unallocated:!g.unallocated&&g.pendingIds.length));$('docDetail').innerHTML=`<section class="bg-slate-900 border border-amber-800 rounded-xl p-4"><h3 class="font-bold mb-2">${id==='docInvoiceReview'?'Invoice coverage review':'Pending invoices'} — current page</h3>${hits.map(g=>`<div class="flex justify-between gap-2 border-t border-slate-800 p-2 text-xs"><span>${esc(g.poNumber)} · ${esc(g.businessName)} · ${g.pendingIds.length} unconfirmed item(s)</span><button class="openInvoiceAlert text-cyan-300" data-key="${esc(g.key)}">Open PO</button></div>`).join('')||'<p class="text-xs text-slate-400">No matching records on this page.</p>'}</section>`;document.querySelectorAll('.openInvoiceAlert').forEach(b=>b.onclick=()=>openPOByKey(b.dataset.key).catch(e=>alert(e.message)));$('docDetail').scrollIntoView({block:'start'});};}
async function applyFilters(){docFilter={po:($('docSearch')?.value||'').trim(),status:($('docStatusFilter')?.value||'').trim()};await refresh(true);render();}
async function clearFilters(){docFilter={po:'',status:''};await refresh(true);render();}
async function changePage(delta){if(delta>0){const end=Math.min(page*PAGE_SIZE+groups.length,total);if(end>=total||!lastDoc)return;page++;}else if(page>0)page--;else return;await refresh(false);render();}
async function switchSide(next){side=next;page=0;cursors=[null];await refresh(true);render();}
async function show(reset=true){if(!can('documents.view'))return;try{await refresh(reset);render();}catch(e){console.error(e);alert('Unable to load Documents: '+(e?.message||e));}}
function install(){const nav=$('navTabs');if(!nav)return;let b=nav.querySelector('[data-tab="invoices"]');if(!b){b=document.createElement('button');b.dataset.tab='invoices';b.className='navBtn text-left px-3 py-2.5 rounded-xl text-xs font-semibold bg-slate-800/50 hover:bg-slate-800';const logs=nav.querySelector('[data-tab="logs"]');logs?logs.before(b):nav.appendChild(b);}b.textContent='Documents';b.onclick=()=>show(true);}
let t;new MutationObserver(()=>{clearTimeout(t);t=setTimeout(install,25)}).observe(document.body,{childList:true,subtree:true});install();window.IMSInvoices=Object.freeze({show,refresh,render,syncLegacyIndex});window.IMSDocuments=window.IMSInvoices;window.dispatchEvent(new CustomEvent('ims:invoices-ready'));export{show,refresh,render};